                {% endif %}
                {%  assign option2Value = selectedVariant.option2 | default: '' %}
                {% if optIdx contains 'option2' %}
                  {%  assign option2Value = value | default: '' %}
                {% endif %}
                {%  assign option3Value = selectedVariant.option3 | default: '' %}
