    {% else %}
      {% if shop.env == 1 %}
        {% include 'slider_product_mock', default_product: default_product, size: product_count %}
      {% endif %}
    {% endunless %}

  {% else %}
    {% comment %} 未选择专辑需要在 B 端 mock 数据 {% endcomment %}
    {% if shop.env == 1 %}
      {% include 'slider_product_mock', default_product: default_product, size: size %}
    {% endif %}
  {% endif %}
