{% javascript %}
$(function () {
  var $slider = $("#slider{{section.id}}");
  $slider.hasClass('slick-initialized') && $slider.slick('destroy');
  $slider.slick({
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: false,
    dots: true,
    infinite: true,
    adaptiveHeight: true,
    touchThreshold: 10,
    speed: 300,
    autoplaySpeed:{{ section.settings.delay }},
    autoplay:{% if section.settings.is_auto_play %}true{%else%}false{%endif%},
    rtl: document.documentElement.getAttribute("dir") == "rtl"
  }).on("beforeChange",function (event, slick){
    $(slick.$slider).find(".lazy-lazyload").removeClass("lazy-lazyload").addClass("lazyload");
  });
  {% comment %} 更新slide高度 {% endcomment %}
  var $slide = $('[data-section-id="{{section.id}}"]');
  $(window).on('resize', function() {
    {% comment %} 更新位移 {% endcomment %}
    {% comment %} 更新banner高度 {% endcomment %}
    $slide.find('.slide_plus__image').height($(window).height() - ($($slide.prevAll('.xfcart-section')[0]).find('.fast-bar').length ? $('.fast-bar').height() : 0));
    $slide.find('.slide_plus__image').width($(window).width());
    {% comment %} swiper.update(); {% endcomment %}
    $(document).trigger('slide__plus_update');
    updateTransform();
  });
  var updateTransform = function (event) {
    if ($($slide.prevAll('.xfcart-section')[0]).find('.header_plus').length) {
      // 上一个卡片是header2,需要位移
      var height = $('#xfcart-section-header_plus').outerHeight() + $('.plugin__fixed-div').outerHeight() + $('.plugin__static-div').outerHeight();
	  if($('.fast-bar').length){
		height = height - $('.fast-bar').outerHeight();
	  }
      $slide.css({
        marginTop: '-' + height + 'px'
      })
    } else {
      $slide.css({
        marginTop: 0
      })
    }
  }
  $(document).on('slide__plus_update', $.throttle(updateTransform));
  $(window).trigger('resize');
})

{% endjavascript %}

