  <style>
    .galina-follow {
      background: linear-gradient(180deg, #fffdfa 0%, #f7efe8 100%);
    }
    .galina-follow__heading {
      margin: 0;
      color: #231916;
      text-align: center;
      font-family: "Baskerville", "Times New Roman", serif;
      font-size: clamp(1.75rem, 3vw, 2.25rem);
      font-weight: 400;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }
    .galina-follow__sub {
      max-width: 42rem;
      margin: 1rem auto 0;
      color: #6a5446;
      text-align: center;
      font-size: 0.98rem;
      line-height: 1.8;
    }
    .galina-follow__grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
      margin-top: 2.2rem;
    }
    .galina-follow__item {
      position: relative;
      display: block;
      overflow: hidden;
      border-radius: 1.4rem;
      box-shadow: 0 18px 42px rgba(69, 45, 30, 0.1);
      aspect-ratio: 1 / 1;
    }
    .galina-follow__item--tall {
      aspect-ratio: 0.78 / 1;
    }
    .galina-follow__item img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.45s ease;
    }
    .galina-follow__item:hover img {
      transform: scale(1.04);
    }
    .galina-follow__item::after {
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(18, 12, 9, 0) 35%, rgba(18, 12, 9, 0.28) 100%);
      content: '';
      pointer-events: none;
    }
    .galina-follow__handle {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      margin: 1.35rem auto 0;
      color: #8c684d;
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }
    .galina-follow__note {
      margin-top: 2.4rem;
      padding: 2rem 2rem 1.8rem;
      border-radius: 1.75rem;
      background: #1e1815;
      box-shadow: 0 24px 54px rgba(30, 24, 21, 0.22);
      text-align: center;
    }
    .galina-follow__note-title {
      color: #fff8f2;
      font-family: "Baskerville", "Times New Roman", serif;
      font-size: clamp(1.75rem, 3vw, 2.35rem);
      font-weight: 400;
      line-height: 1.12;
    }
    .galina-follow__note-text {
      max-width: 38rem;
      margin: 1rem auto 0;
      color: rgba(255, 244, 237, 0.78);
      font-size: 0.97rem;
      line-height: 1.8;
    }
    .galina-follow__note-cta {
      display: inline-flex;
      align-items: center;
