      {% comment %} 加购信息补充区域 {% endcomment %}
      {% if settings.additional_text or settings.additional_image_pc or settings.additional_image_mobile %}
        {% unless REQUEST_URI contains "view=ajax" %}
          <div class="product-info__additional">
